import java.io.*;import java.util.*;public class Main{public static void main(String[] args) throws IOException{BufferedReader br=new BufferedReader(new InputStreamReader(System.in));StringBuilder out=new StringBuilder();int T=Integer.parseInt(br.readLine().trim());while(T-- >0){String s1=br.readLine().trim();String s2=br.readLine().trim();int n=s1.length();int minDiff=0;int maxDiff=0;for(int i=0;i<n;i++){char c1=s1.charAt(i);char c2=s2.charAt(i);if(c1!='?' && c2!='?'){if(c1!=c2){minDiff++;maxDiff++;}}else{maxDiff++;}}out.append(minDiff).append(' ').append(maxDiff).append('\n');}System.out.print(out.toString());}}